def _kill_process_group(proc: subprocess.Popen) -> None:
    pgid = os.getpgid(proc.pid)
    for sig in (signal.SIGTERM, signal.SIGKILL):
        os.killpg(pgid, sig)
        proc.wait(timeout=5)

